#!/bin/zsh
set -eu
cd "${0:A:h}"
ruby tests/test_asset_importer.rb
ruby tests/test_content_editor_import.rb
ruby tests/test_lore_export.rb
ruby tools/build_lore.rb --check
ruby tests/test_world_asset_builder.rb
ruby tools/build_world_assets.rb --check
ruby tests/test_content_bundles.rb
ruby tests/test_network_manifest.rb
ruby tests/test_release_inputs.rb
ruby tools/build_content_bundles.rb --check
ruby tools/import_assets.rb --check
check_log=$(mktemp -t endlessdungeon-check)
trap 'rm -f "$check_log"' EXIT
./godot.sh --headless --editor --quit >"$check_log" 2>&1
if rg -q 'SCRIPT ERROR:|ERROR:|WARNING:' "$check_log"; then
  cat "$check_log"
  exit 1
fi
for check in tests/test_dimension_terrain.gd tests/test_dimension_constructions.gd tests/test_dimension_population.gd tests/test_morrowmere_content.gd tests/test_morrowmere_roaming.gd tests/test_finite_world.gd tests/test_dimension_map.gd tests/test_minimap_cache.gd tests/test_dimension_travel.gd tests/test_dimension_revision.gd tests/test_remote_world.gd tests/test_online_client.gd tests/test_online_endpoints.gd tests/test_asset_registry.gd tests/test_player_text.gd tests/test_streaming.gd tests/test_streaming_defer.gd tests/test_worldgate_streaming.gd tests/test_release_runtime.gd tests/test_terrain_mesh_data.gd tests/test_render_warmup.gd tests/test_render_camera_warmup.gd tests/test_render_cache_selection.gd tests/test_render_cache_retention.gd tests/test_render_cache.gd tests/test_landmark_cache.gd tests/test_lore.gd tests/test_content_bundles.gd tests/test_content_edits.gd tests/test_content_edit_contracts.gd tests/test_content_editor_assets.gd tests/test_content_editor_publication.gd tests/test_content_editor_runtime.gd tests/test_content_editor_removal.gd tests/test_enemy_loot.gd tests/test_kill_rewards.gd tests/test_bundle_gameplay.gd tests/test_visibility_display.gd tests/test_world_content.gd tests/test_voxel_monsters.gd tests/test_voxel_monsters_game.gd tests/test_enemies.gd tests/test_animated_style_conversion.gd tests/test_creature_styles.gd tests/test_creature_styles_game.gd tests/test_interiors.gd tests/test_interior_styles.gd tests/test_interior_styles_game.gd tests/test_world_life_catalog.gd tests/test_world_life.gd tests/test_wilderness_roamers.gd tests/test_wilderness_roamers_game.gd tests/test_wonder_creatures.gd tests/test_wonder_hub_game.gd tests/test_wonder_npcs.gd tests/test_wonder_models.gd tests/test_world_activity.gd tests/test_monster_areas.gd tests/test_monster_packs.gd tests/test_surface_travel.gd tests/test_world_activity_game.gd tests/test_stores.gd tests/test_foraging.gd tests/test_city_law.gd tests/test_city_law_game.gd tests/test_dynamic_scenery.gd tests/test_assets.gd tests/test_progression.gd tests/test_traversal.gd tests/test_world.gd tests/test_site_planner.gd tests/test_road_polish.gd tests/test_independent_world.gd tests/test_independent_game.gd tests/test_surface_locations.gd tests/test_surface_location_models.gd tests/test_surface_locations_game.gd tests/test_landscape.gd tests/test_town_magic.gd tests/test_town_magic_game.gd tests/test_local_decor_styles.gd tests/test_local_decor_game.gd tests/test_town_types.gd tests/test_town_types_game.gd tests/test_generation_routes.gd tests/test_dungeon.gd tests/test_dungeon_purpose.gd tests/test_dungeon_styles.gd tests/test_dungeon_styles_game.gd tests/test_voxel_characters.gd tests/test_voxel_characters_game.gd tests/test_npc_families.gd tests/test_npc_expansion.gd tests/test_gameplay.gd tests/test_camera.gd tests/test_save_game.gd tests/test_integer_save_contracts.gd tests/test_world_edition_saves.gd tests/test_foraging_edition7.gd tests/test_micro_biomes.gd tests/test_micro_biome_view.gd tests/test_micro_biome_game.gd tests/test_biome_landmarks.gd tests/test_biome_landmark_world.gd tests/test_biome_landmark_models.gd tests/test_biome_landmark_game.gd tests/test_biome_landmark_journal.gd tests/test_biome_composition.gd tests/test_biome_composition_game.gd tests/test_biome_crowns.gd tests/test_biome_atmosphere.gd tests/test_composition_editions.gd tests/test_composition_worker.gd tests/test_biome_regions.gd tests/test_biome_transitions.gd tests/test_biome_coast.gd tests/test_biome_models.gd tests/test_biome_edition_compatibility.gd tests/test_biome_game.gd tests/test_biome_new_journey.gd tests/test_sanctum.gd tests/test_worldgate_progress.gd tests/test_character_inventory.gd tests/test_icon_grids.gd tests/test_character_styles.gd tests/test_player_wardrobe.gd tests/test_save_exit.gd tests/test_expansion.gd tests/test_world_ambience.gd tests/test_combat_audio.gd tests/test_combat_audio_game.gd tests/test_summon_dispositions.gd tests/test_expanded_spell_catalogue.gd tests/test_combat_summons.gd tests/test_spell_effects_game.gd tests/test_world_construction.gd tests/test_town_model_voxelizer.gd tests/test_town_architecture.gd tests/test_town_voxel_assets.gd tests/test_town_voxel_integration.gd tests/test_town_fallback_styles.gd tests/test_town_fallback_game.gd tests/test_environment_styles.gd tests/test_cultural_styles.gd tests/test_exploration.gd tests/test_site_knowledge.gd tests/test_contextual_placement.gd tests/test_wall_support.gd tests/test_regional_history.gd tests/test_local_quests.gd tests/test_sparse_regional_targets.gd tests/test_sparse_regional_game.gd tests/test_world_items.gd tests/test_world_items_game.gd tests/test_surface_items.gd tests/test_item_stacks.gd tests/test_item_stacks_game.gd tests/test_icon_item_geometry.gd tests/test_item_styles.gd tests/test_placed_item_styles.gd tests/test_item_styles_game.gd tests/test_furnishings.gd tests/test_furnished_home.gd tests/test_floating_city.gd tests/test_floating_city_game.gd; do
  check_frames=600
  [[ "$check" == tests/test_streaming.gd || "$check" == tests/test_streaming_defer.gd || "$check" == tests/test_worldgate_streaming.gd || "$check" == tests/test_release_runtime.gd ]] && check_frames=3600
  ./godot.sh --headless --script "$check" --quit-after "$check_frames" >"$check_log" 2>&1
  cat "$check_log"
  if rg -q 'SCRIPT ERROR:|ERROR:|WARNING:' "$check_log" || ! rg -q '^PASS:' "$check_log"; then
    exit 1
  fi
done
